<?php require __DIR__ . '/../partials/header.php'; ?>
<div class="card" style="max-width:700px;margin:0 auto;"><div class="card-header"><h1>Reviews</h1><p>Rate and review purchased products.</p></div><?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?><?php if($successMsg):?><div class="alert alert-success"><?php echo e($successMsg);?></div><?php endif;?>
<?php if(!$purchased_products):?><p class="muted">You haven't purchased anything yet.</p><?php else:?><form method="post" action="<?php echo e(url_for('customer','reviews'));?>"><?php echo csrf_field();?><div class="field"><label>Product</label><select name="product_id"><?php foreach($purchased_products as $pp):?><option value="<?php echo e($pp['id']);?>"><?php echo e($pp['name']);?> (#<?php echo e($pp['id']);?>)</option><?php endforeach;?></select></div><div class="field"><label>Rating</label><select name="rating"><option value="5">5 ★ Excellent</option><option value="4">4 ★ Good</option><option value="3">3 ★ Average</option><option value="2">2 ★ Poor</option><option value="1">1 ★ Terrible</option></select></div><div class="field"><label>Comment</label><textarea name="comment" rows="2"></textarea></div><button class="btn btn-primary btn-block">Post Review</button></form><?php endif;?></div>
<div class="card"><div class="card-header"><h2>Your Reviews</h2></div><?php if(!$my_reviews):?><p class="muted">No reviews yet.</p><?php else:?><table class="data-table"><tr><th>Product</th><th>Rating</th><th>Comment</th><th>Date</th></tr><?php foreach($my_reviews as $r):?><tr><td><?php echo e($r['product_name']);?></td><td><?php echo e(str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating']));?></td><td><?php echo $r['comment']?e($r['comment']):'—';?></td><td class="small"><?php echo e($r['created_at']);?></td></tr><?php endforeach;?></table><?php endif;?></div>
<?php require __DIR__ . '/../partials/footer.php'; ?>
